{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-huashu-pentagram-grid",
  "title": "Pentagram Info-Architecture",
  "title_i18n": {
    "en": "Pentagram Info-Architecture",
    "zh-CN": "信息建筑·红"
  },
  "version": "1.0.0",
  "description": "Rational Swiss-grid data decks: black-and-white restraint, Helvetica Neue hierarchy, one red (#E63946), 64px black chrome bars, 5%-opacity grid hairlines, and 260px giant numerals anchoring red/dark/grey comparison bar charts on a fixed 1920×1080 canvas. Based on https://github.com/alchaincyf/huashu-design ppt-pentagram, expanded from a single showcase page into a full multi-section deck.",
  "description_i18n": {
    "en": "Rational Swiss-grid data decks: black-and-white restraint, Helvetica Neue hierarchy, one red (#E63946), 64px black chrome bars, 5%-opacity grid hairlines, and 260px giant numerals anchoring red/dark/grey comparison bar charts on a fixed 1920×1080 canvas. Based on https://github.com/alchaincyf/huashu-design ppt-pentagram, expanded from a single showcase page into a full multi-section deck.",
    "zh-CN": "理性信息建筑派数据幻灯片：黑白克制的瑞士网格、Helvetica Neue 强层级、唯一红色 #E63946、上下 64px 黑色信息条、5% 透明度网格细线、260px 巨型数字锚点压红/黑/灰对比条形图，1920×1080 固定画布、零外部依赖。基于花叔 huashu-design 的 ppt-pentagram 单页范本扩展为完整多章节 deck。"
  },
  "license": "MIT",
  "author": {
    "name": "花叔 (alchaincyf)",
    "url": "https://github.com/alchaincyf"
  },
  "homepage": "https://github.com/alchaincyf/huashu-design",
  "plugin": {
    "repo": "https://github.com/alchaincyf/huashu-design"
  },
  "tags": [
    "community",
    "deck",
    "slides",
    "ppt",
    "presentation",
    "swiss-grid",
    "data-report",
    "minimal",
    "huashu"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "deck",
    "scenario": "product",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html",
      "motion": "deck"
    },
    "useCase": {
      "query": {
        "en": "Create a Swiss-grid {{deckType}} for {{audience}} about {{topic}} with {{slideCount}}, using the Pentagram Info-Architecture system (based on huashu-design ppt-pentagram): a fixed 1920×1080 canvas auto-scaled to the viewport; white pages framed by 64px solid-black chrome bars top and bottom (uppercase tracked labels, red `/` separator, red right-hand label, 900-weight logotype + footnote in the bottom bar); absolutely-positioned 1px grid hairlines at 5% opacity on 80px outer gutters; the single font stack 'Helvetica Neue'/PingFang SC with zero external dependencies; exactly one accent #E63946 used for ≤4 touches per page (red decimal/slash inside giant numerals, red winning bars, red kicker numbers, red punctuation in headlines). Every hero page is anchored by one 180–260px weight-900 negative-tracked numeral; comparisons use the locked red/dark/grey horizontal bar system (right-aligned 90px labels, #F5F5F5 tracks, values printed inside the fill, the page's subject always the red bar, optional red uppercase delta line). Draw layouts from the locked enumeration: cover / contents / big-number / data-theater (left hero column + 2–3 bench columns + hairline summary strip) / dark divider / two-column before-after / timeline / quote / stats-grid / dark closing — white pages dominate with at most 2–3 dark pages. No emoji, no gradients, no shadows, no border-radius, no second color, no second font. Build a single self-contained HTML file by copying example.html and replacing content only — keep its design tokens, chrome bars, grid hairlines, and navigation script (←/→/Space keys, #/N hash routing, click zones, counter pill) intact. Use the user's real numbers, never lorem ipsum or invented data; Chinese copy uses 「」 quotes; replace all fictional 析衡/XIHENG demo content.",
        "zh-CN": "用「信息建筑·红」体系为 {{audience}} 做一套关于 {{topic}} 的 {{deckType}}（页数 {{slideCount}}）：1920×1080 固定画布、上下 64px 黑色信息条、5% 透明度瑞士网格细线、Helvetica Neue 单一字体栈零外部依赖、唯一红色 #E63946 每页最多 4 处、180–260px 巨型数字锚点、红/黑/灰三色对比条形图，版式从封面/目录/巨数/数据剧场/暗色分隔/前后对照/里程碑/引语/指标矩阵/暗色结尾枚举中取用。从 example.html 复制出单文件、只换内容，保留 token、信息条、网格线和导航脚本；用真实数据、替换全部「析衡」演示内容。完整规格以英文版为准（follow the en query above）。"
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Pentagram Info-Architecture",
          "title_i18n": {
            "en": "Pentagram Info-Architecture",
            "zh-CN": "信息建筑·红"
          }
        }
      ]
    },
    "inputs": [
      {
        "name": "deckType",
        "label": "Deck type",
        "type": "select",
        "required": true,
        "options": [
          "data / benchmark report deck",
          "annual report deck",
          "KPI / business review deck",
          "product metrics deck",
          "research findings deck"
        ],
        "default": "data / benchmark report deck"
      },
      {
        "name": "topic",
        "label": "Topic",
        "type": "string",
        "required": true,
        "placeholder": "你的主题，例如：2026 年度增长数据复盘",
        "default": "the user's brief"
      },
      {
        "name": "audience",
        "label": "Audience",
        "type": "string",
        "required": true,
        "placeholder": "董事会 / 投资人 / 全员大会",
        "default": "decision makers"
      },
      {
        "name": "slideCount",
        "label": "Pages",
        "type": "select",
        "required": true,
        "options": [
          "8 pages",
          "9-10 pages",
          "10-11 pages"
        ],
        "default": "9-10 pages"
      }
    ],
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "discovery",
          "atoms": [
            "discovery-question-form"
          ]
        },
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ]
  }
}
